Method.Implementation:
$$$TRACE("Inside "_..%ConfigName_" Method ProcessTacticalDbAdtRequest")

set pResponse = ##class(EnsLib.SQL.Snapshot).%New()

set tSQL = "SELECT * FROM CARDIORISINTERFACE.CARDIO_ORDER WHERE ACCESSION_NO ='"_pRequest.ACCESSIONNO_"'"

set tSC = ..Adapter.ExecuteQuery(.pResponse,tSQL)

if tSC = 1{
	$$$TRACE("Successfully executed Query:"_tSQL)
	set rowCount = pResponse.RowCount
	$$$TRACE("Row Count:"_rowCount)
	if (rowCount = 0){
		$$$TRACE("About to Insert in the Orders table..")
		set tSC = ..InsertQuery(pRequest) 
	}else{
		$$$TRACE("About to Update in the Orders table..")
		set tSC = ..UpdateQuery(pRequest) 
		$$$TRACE(" Updated Successfully..")
    }
}else{
	$$$TRACE("Failed to execute Query:"_tSQL)	
}

Quit tSC
